sys_script_include.script:
var wsdl_clm = Class.create();
wsdl_clm.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getlimit: function(){
		var credlimit = this.getParameter('sysparm_customer_code');
    var req = new sn_ws.RESTMessageV2();
    // Unescape the endpoint (real '&' not &amp;)
    req.setEndpoint('https://speed.eye2serve.com:7777/XISOAPAdapter/MessageServlet?senderParty=&senderService=BC_OneUltratech&receiverParty=&receiverService=&interface=SI_Customer_AVL_Credit_Limit_REQ&interfaceNamespace=http://Oneultratechapp.com/OUS/Customer_AVL_Credit_Limit');
    // Correct headers for SOAP 1.1
    req.setRequestHeader('Content-Type', 'text/xml; charset=utf-8');
    req.setRequestHeader('Accept', 'text/xml');
req.setHttpMethod('POST');
    var body =
      '<?xml version="1.0" encoding="UTF-8"?>' +
      '<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:cus="http://Oneultratechapp.com/OUS/Customer_AVL_Credit_Limit">' +
      '  <soapenv:Header/>' +
      '  <soapenv:Body>' +
      '    <cus:MT_Customer_AVL_Credit_Limit_REQ>' +
      // NOTE: Depending on the provider’s schema, this child element may need the 'cus' prefix as well.
      // If they require namespaced children, change to <cus:Customer_Code>...</cus:Customer_Code>
      '      <CUSTOMER_CODE>'+credlimit+'</CUSTOMER_CODE>' +
      '    </cus:MT_Customer_AVL_Credit_Limit_REQ>' +
      '  </soapenv:Body>' +
      '</soapenv:Envelope>';

    req.setRequestBody(body);
    req.setBasicAuth('po_wsdl', 'Poqa@2019');

    // Optional: timeout and MID routing
    req.setHttpTimeout(60000);
    // req.setMIDServer('YOUR_MID_NAME'); // if endpoint is reachable only via MID

    var res = req.execute();
    var status = res.getStatusCode();
    var bodyOut = res.getBody();
    var err = res.getErrorMessage();

   // gs.info('[SOAP via REST] HTTP ' + status);
   // gs.info(bodyOut);

var x = new XMLDocument2();
x.parseXML(bodyOut);

var cred = x.getNodeText("//*[local-name()='LT_OUT']/*[local-name()='item']/*[local-name()='AVAILABLE_CREDIT_LIMIT']");
return cred;
	},
    type: 'wsdl_clm'
});
